import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import {
  GITHUB_LOCKFILE,
  compareLockfiles,
  findLockfile,
  parseGitHubLockfile,
  parseSecureciLockfile,
  readLockfile,
  serializeSecureciLockfile
} from './github-lockfile';
import { memoryFiles } from './utils/files';

// Shape written by `gh actions-lock` (github/gh-actions-lock), v0.0.2.
const SAMPLE = [
  '# This file is machine-generated by `gh actions-lock`.',
  "version: 'v0.0.2'",
  'workflows:',
  "    '.github/workflows/ci.yml':",
  "        - 'actions/checkout@v5.0.1'",
  "        - 'github/codeql-action/upload-sarif@v3'",
  'dependencies:',
  "    'actions/checkout@v5.0.1':",
  "        ref: 'v5.0.1'",
  "        commit: 'sha1-93cb6efe18208431cddfb8368fd83d5badbf9bfd'",
  '        owner_id: 44036562',
  '        repo_id: 197814629',
  "    'github/codeql-action/upload-sarif@v3':",
  "        ref: 'v3'",
  "        commit: 'sha1-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa'",
  '        owner_id: 1',
  '        repo_id: 2',
  '        uses:',
  "            - 'actions/attest@67422f5511b7ff725f4dbd6fb9bd2cd925c65a8d'",
  "    'actions/attest@67422f5511b7ff725f4dbd6fb9bd2cd925c65a8d':",
  "        ref: 'v1.4.1'",
  "        commit: 'sha1-67422f5511b7ff725f4dbd6fb9bd2cd925c65a8d'",
  '        owner_id: 44036562',
  '        repo_id: 760701061'
].join('\n');

describe('parseGitHubLockfile', () => {
  it('maps each dependency to its locked commit and repository identity', () => {
    expect(parseGitHubLockfile(SAMPLE)).toEqual({
      version: 2,
      actions: {
        'actions/checkout@v5.0.1': {
          commit: '93cb6efe18208431cddfb8368fd83d5badbf9bfd',
          ownerId: 44036562,
          repoId: 197814629
        },
        'github/codeql-action/upload-sarif@v3': {
          commit: 'a'.repeat(40),
          ownerId: 1,
          repoId: 2
        },
        'actions/attest@67422f5511b7ff725f4dbd6fb9bd2cd925c65a8d': {
          commit: '67422f5511b7ff725f4dbd6fb9bd2cd925c65a8d',
          ownerId: 44036562,
          repoId: 760701061
        }
      }
    });
  });

  it('leaves out an identity that is not a number', () => {
    const lock = parseGitHubLockfile(
      SAMPLE.replace('owner_id: 44036562', "owner_id: 'x'")
    );
    expect(lock.actions['actions/checkout@v5.0.1']).toEqual({
      commit: '93cb6efe18208431cddfb8368fd83d5badbf9bfd',
      repoId: 197814629
    });
  });

  it('accepts v0.0.3', () => {
    const lock = parseGitHubLockfile(SAMPLE.replace('v0.0.2', 'v0.0.3'));
    expect(Object.keys(lock.actions)).toHaveLength(3);
  });

  it('rejects a version it does not understand', () => {
    expect(() =>
      parseGitHubLockfile(SAMPLE.replace('v0.0.2', 'v0.1.0'))
    ).toThrow(/Unsupported actions\.lock version "v0\.1\.0"/);
  });

  it('rejects a dependency without a sha1 commit', () => {
    expect(() =>
      parseGitHubLockfile(SAMPLE.replace('sha1-93cb6efe', 'sha256-93cb6efe'))
    ).toThrow(/actions\/checkout@v5\.0\.1/);
  });

  it('rejects a file that is not a lockfile', () => {
    expect(() => parseGitHubLockfile('just: text')).toThrow(
      /Unsupported actions\.lock version/
    );
  });
});

describe('findLockfile', () => {
  let dir: string;
  const write = (rel: string) => {
    fs.mkdirSync(path.dirname(path.join(dir, rel)), { recursive: true });
    fs.writeFileSync(path.join(dir, rel), '');
  };

  beforeEach(() => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), 'secureci-lockfind-'));
  });
  afterEach(() => fs.rmSync(dir, { recursive: true, force: true }));

  it('finds nothing in an empty repo', () => {
    expect(findLockfile(dir)).toBeUndefined();
  });

  it("uses GitHub's actions.lock when it is the only lockfile", () => {
    write(GITHUB_LOCKFILE);
    expect(findLockfile(dir)).toEqual({
      kind: 'github',
      file: path.join(dir, GITHUB_LOCKFILE)
    });
  });

  it('prefers secureci.lock when both exist', () => {
    write(GITHUB_LOCKFILE);
    write('secureci.lock');
    expect(findLockfile(dir)).toEqual({
      kind: 'secureci',
      file: path.join(dir, 'secureci.lock')
    });
  });
});

describe('findLockfile and readLockfile on given files', () => {
  it("finds and reads GitHub's actions.lock among in-memory files", () => {
    const files = memoryFiles({ '.github/workflows/actions.lock': SAMPLE });
    const source = findLockfile('', files);
    expect(source).toEqual({ kind: 'github', file: GITHUB_LOCKFILE });
    expect(readLockfile(source!, files)).toEqual(parseGitHubLockfile(SAMPLE));
  });

  it('throws when the lockfile is not among the files', () => {
    expect(() =>
      readLockfile({ kind: 'secureci', file: 'secureci.lock' }, memoryFiles({}))
    ).toThrow('Lockfile not found: secureci.lock');
  });
});

describe('secureci.lock', () => {
  const a = 'a'.repeat(40);
  const b = 'b'.repeat(40);

  it('reads a version 1 lock (commit strings)', () => {
    expect(
      parseSecureciLockfile(
        JSON.stringify({ version: 1, actions: { 'org/scan@v1': a } })
      )
    ).toEqual({ version: 1, actions: { 'org/scan@v1': { commit: a } } });
  });

  it('reads a version 2 lock with identities and via', () => {
    const text = JSON.stringify({
      version: 2,
      actions: {
        'org/scan@v1': { commit: a, owner_id: 7, repo_id: 8 },
        'org/helper@v2': { commit: b, via: ['org/scan@v1'] }
      }
    });
    expect(parseSecureciLockfile(text)).toEqual({
      version: 2,
      actions: {
        'org/scan@v1': { commit: a, ownerId: 7, repoId: 8 },
        'org/helper@v2': { commit: b, via: ['org/scan@v1'] }
      }
    });
  });

  it('rejects an unknown version or a malformed entry', () => {
    expect(() =>
      parseSecureciLockfile(JSON.stringify({ version: 3, actions: {} }))
    ).toThrow(/Unsupported secureci.lock version "3"/);
    expect(() =>
      parseSecureciLockfile(
        JSON.stringify({
          version: 2,
          actions: { 'org/scan@v1': { commit: 'x' } }
        })
      )
    ).toThrow(/org\/scan@v1/);
    expect(() => parseSecureciLockfile('not json')).toThrow();
  });

  it('writes version 2, sorted, and reads back what it wrote', () => {
    const actions = {
      'org/z@v1': { commit: b, via: ['org/a@v1'] },
      'org/a@v1': { commit: a, ownerId: 1, repoId: 2 }
    };
    const text = serializeSecureciLockfile(actions);
    expect(JSON.parse(text)).toEqual({
      version: 2,
      actions: {
        'org/a@v1': { commit: a, owner_id: 1, repo_id: 2 },
        'org/z@v1': { commit: b, via: ['org/a@v1'] }
      }
    });
    expect(Object.keys(JSON.parse(text).actions)).toEqual([
      'org/a@v1',
      'org/z@v1'
    ]);
    expect(text.endsWith('\n')).toBe(true);
    expect(parseSecureciLockfile(text)).toEqual({ version: 2, actions });
  });

  it('readLockfile reads either kind', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'secureci-lockread-'));
    const secureci = path.join(dir, 'secureci.lock');
    fs.writeFileSync(
      secureci,
      serializeSecureciLockfile({ 'org/a@v1': { commit: a } })
    );
    expect(readLockfile({ kind: 'secureci', file: secureci }).actions).toEqual({
      'org/a@v1': { commit: a }
    });
    const github = path.join(dir, 'actions.lock');
    fs.writeFileSync(github, SAMPLE);
    expect(
      Object.keys(readLockfile({ kind: 'github', file: github }).actions)
    ).toHaveLength(3);
    fs.rmSync(dir, { recursive: true, force: true });
  });
});

describe('compareLockfiles', () => {
  const a = 'a'.repeat(40);
  const b = 'b'.repeat(40);

  it('finds nothing when every shared reference agrees', () => {
    expect(
      compareLockfiles(
        { 'org/a@v1': { commit: a, ownerId: 1, repoId: 2 } },
        { 'org/a@v1': { commit: a, ownerId: 1, repoId: 2 } }
      )
    ).toEqual([]);
  });

  it('reports a reference locked at different commits', () => {
    expect(
      compareLockfiles(
        { 'org/a@v1': { commit: a } },
        { 'org/a@v1': { commit: b } }
      )
    ).toEqual([{ uses: 'org/a@v1', field: 'commit', secureci: a, github: b }]);
  });

  it('reports a different repository identity, only where both record it', () => {
    expect(
      compareLockfiles(
        {
          'org/a@v1': { commit: a, ownerId: 1, repoId: 2 },
          'org/b@v1': { commit: a, repoId: 5 }
        },
        {
          'org/a@v1': { commit: a, ownerId: 9, repoId: 3 },
          'org/b@v1': { commit: a, ownerId: 7 }
        }
      )
    ).toEqual([
      { uses: 'org/a@v1', field: 'owner_id', secureci: 1, github: 9 },
      { uses: 'org/a@v1', field: 'repo_id', secureci: 2, github: 3 }
    ]);
  });

  it('ignores references in only one of the files', () => {
    // gh actions-lock narrows refs (v4 -> v4.2.1) and records dependencies
    // SecureCI doesn't follow, so one-sided keys aren't disagreements.
    expect(
      compareLockfiles(
        { 'org/a@v1': { commit: a } },
        { 'org/b@v1': { commit: b } }
      )
    ).toEqual([]);
  });

  it('lists disagreements sorted by reference', () => {
    const found = compareLockfiles(
      { 'org/z@v1': { commit: a }, 'org/a@v1': { commit: a } },
      { 'org/z@v1': { commit: b }, 'org/a@v1': { commit: b } }
    );
    expect(found.map((m) => m.uses)).toEqual(['org/a@v1', 'org/z@v1']);
  });
});

// One workflow with the secureci.lock that `secureci inventory --update-lock`
// writes for it and the actions.lock that `gh actions-lock` writes for it
// (test/fixtures/lockfiles). Both must pin every action at the same commit.
describe('secureci.lock and actions.lock for the same workflow', () => {
  const fixtures = path.join(__dirname, '..', 'test', 'fixtures', 'lockfiles');
  const read = (name: string) =>
    fs.readFileSync(path.join(fixtures, name), 'utf-8');
  const secureci = parseSecureciLockfile(read('secureci.lock')).actions;
  const github = parseGitHubLockfile(read('actions.lock')).actions;
  const workflowUses = [...read('ci.yml').matchAll(/uses:\s*([^\s#]+)/g)].map(
    (m) => m[1]
  );

  it('locks every action the workflow uses in both files', () => {
    expect(workflowUses.length).toBeGreaterThan(0);
    for (const uses of workflowUses) {
      expect(secureci[uses], `${uses} in secureci.lock`).toBeDefined();
      expect(github[uses], `${uses} in actions.lock`).toBeDefined();
    }
  });

  it('records the same commit SHA and repository identity in both', () => {
    for (const uses of workflowUses) {
      expect(secureci[uses].commit).toBe(github[uses].commit);
      expect(secureci[uses].ownerId).toBe(github[uses].ownerId);
      expect(secureci[uses].repoId).toBe(github[uses].repoId);
    }
    expect(compareLockfiles(secureci, github)).toEqual([]);
  });

  it('pins each SHA-pinned reference at the SHA it names', () => {
    for (const uses of workflowUses) {
      const pinned = uses.split('@')[1];
      expect(secureci[uses].commit).toBe(pinned);
      expect(github[uses].commit).toBe(pinned);
    }
  });
});
